package com.example.app08.auth; import java.util.Map; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/auth") public class AuthController { @PostMapping("/login") public Map<String,String> login(){return Map.of("accessToken","demo-token","refreshToken","demo-refresh");} @PostMapping("/register") public Map<String,String> register(){return Map.of("status","registered");} @PostMapping("/refresh") public Map<String,String> refresh(){return Map.of("accessToken","demo-token-refreshed");} @PostMapping("/logout") public Map<String,String> logout(){return Map.of("status","logged-out");} @GetMapping("/me") public Map<String,String> me(){return Map.of("email","admin@app08.local","role","ADMIN");} }
